css:
body {
    font-family: "Segoe UI", Tahoma, Geneva, Verdana, sans-serif;
    font-size: 14px;
    color: #333;
    margin: 30px;
}

h3 {
    font-size: 22px;
    text-align: left;
    color: #2f4f4f;
    margin-bottom: 10px;
}

h4 {
    font-size: 18px;
    margin-top: 30px;
    color: #2e3e4e;
    border-bottom: 1px solid #ccc;
    padding-bottom: 5px;
}

strong {
    color: #1a1a1a;
}

table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 20px;
    background-color: #fafafa;
}

table th {
    padding: 10px;
    font-weight: bold;
    border: 1px solid #ddd;
    text-align: left;
}

table td {
    padding: 8px 10px;
    border: 1px solid #ddd;
    text-align: left;
}

ol {
    padding-left: 20px;
    margin-top: 10px;
}

hr {
    margin-top: 30px;
    margin-bottom: 20px;
    border: none;
    border-top: 1px solid #ccc;
}

.signature-table,
.place-date-table {
    width: 100%;
    font-size: 13px;
    margin-top: 40px;
}

.signature-table td {
    text-align: center;
    padding-top: 30px;
}

.place-date-table td {
    padding: 5px 0;
}
